  };

  return Response.json(newPost, { status: 201 });
}

import type { ApiPost, UpdatePostRequest } from '@/types/blog';

interface RouteHandlerContext {
  params: Promise<{ id: string }>;
}

function parsePostId(id: string): number | null {
  const parsedId = Number.parseInt(id, 10);

  if (Number.isNaN(parsedId)) {
    return null;
  }

  return parsedId;
}

export async function GET(
  _request: Request,
  { params }: RouteHandlerContext
): Promise<Response> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: ApiPost = {
    id: parsedId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return Response.json(post);
}

export async function PUT(
  request: Request,
  { params }: RouteHandlerContext
): Promise<Response> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: Partial<UpdatePostRequest>;

  try {
    body = (await request.json()) as Partial<UpdatePostRequest>;
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost: ApiPost = {
    id: parsedId,
    title: body.title?.trim() || `Post ${id}`,
    content: body.content?.trim() || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return Response.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: RouteHandlerContext
): Promise<Response> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return Response.json({ message: `Post ${id} deleted successfully` });
}

