const JSON_PLACEHOLDER_BASE_URL = 'https://jsonplaceholder.typicode.com';

interface RevalidateFetchOptions extends RequestInit {
  next?: {
    revalidate?: number;
  };
}

async function fetchJson<T>(
  path: string,
  options?: RevalidateFetchOptions
): Promise<T> {
  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}${path}`, options);

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  return (await response.json()) as T;
}

export async function getRecentPosts(): Promise<Post[]> {
  return fetchJson<Post[]>('/posts?_limit=5', { cache: 'no-store' });
}

export async function getAllPosts(): Promise<Post[]> {
  return fetchJson<Post[]>('/posts', { next: { revalidate: 60 } });
}

export async function getStaticBlogParams(): Promise<Array<{ id: string }>> {
  const posts = await fetchJson<Post[]>('/posts', { next: { revalidate: 3600 } });

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function getPostById(id: string): Promise<Post | null> {
  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}/posts/${id}`, {
    next: { revalidate: 300 },
  });

  if (response.status === 404) {
    return null;
  }

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const post = (await response.json()) as Post;

  if (!post?.id) {
    return null;
  }

  return post;
}

export async function getCommentsByPostId(id: string): Promise<Comment[]> {
  return fetchJson<Comment[]>(`/posts/${id}/comments`, {
    next: { revalidate: 300 },
  });
}

