 3	interface RouteHandlerContext {
 4	  params: Promise<{ id: string }>;
 5	}
 6	
 7	function parsePostId(id: string): number | null {
 8	  const parsedId = Number.parseInt(id, 10);
 9	
10	  if (Number.isNaN(parsedId)) {
11	    return null;
12	  }
13	
14	  return parsedId;
15	}
16	
17	export async function GET(
18	  _request: Request,
19	  { params }: RouteHandlerContext
20	): Promise<Response> {
21	  const { id } = await params;
22	  const parsedId = parsePostId(id);
23	
24	  if (parsedId === null) {
25	    return Response.json({ error: 'Invalid post id' }, { status: 400 });
26	  }
27	
28	  const post: ApiPost = {
29	    id: parsedId,
30	    title: `Post ${id}`,
31	    content: `This is the content for post ${id}`,
32	    createdAt: new Date().toISOString(),
33	  };
34	
35	  return Response.json(post);
36	}
37	
38	export async function PUT(
39	  request: Request,
40	  { params }: RouteHandlerContext
41	): Promise<Response> {
42	  const { id } = await params;
43	  const parsedId = parsePostId(id);
44	
45	  if (parsedId === null) {
46	    return Response.json({ error: 'Invalid post id' }, { status: 400 });
47	  }
48	
49	  let body: Partial<UpdatePostRequest>;
50	
51	  try {
52	    body = (await request.json()) as Partial<UpdatePostRequest>;
53	  } catch {
54	    return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
55	  }
56	
57	  const updatedPost: ApiPost = {
58	    id: parsedId,
59	    title: body.title?.trim() || `Post ${id}`,
60	    content: body.content?.trim() || `Updated content for post ${id}`,
61	    updatedAt: new Date().toISOString(),
62	  };
63	
64	  return Response.json(updatedPost);
65	}
66	
67	export async function DELETE(
68	  _request: Request,
69	  { params }: RouteHandlerContext
70	): Promise<Response> {
71	  const { id } = await params;
72	  const parsedId = parsePostId(id);
73	
74	  if (parsedId === null) {
75	    return Response.json({ error: 'Invalid post id' }, { status: 400 });
76	  }
77	
78	  return Response.json({ message: `Post ${id} deleted successfully` });
79	}

