 2	
 3	const JSON_PLACEHOLDER_BASE_URL = 'https://jsonplaceholder.typicode.com';
 4	
 5	interface RevalidateFetchOptions extends RequestInit {
 6	  next?: {
 7	    revalidate?: number;
 8	  };
 9	}
10	
11	async function fetchJson<T>(
12	  path: string,
13	  options?: RevalidateFetchOptions
14	): Promise<T> {
15	  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}${path}`, options);
16	
17	  if (!response.ok) {
18	    throw new Error(`Request failed with status ${response.status}`);
19	  }
20	
21	  return (await response.json()) as T;
22	}
23	
24	export async function getRecentPosts(): Promise<Post[]> {
25	  return fetchJson<Post[]>('/posts?_limit=5', { cache: 'no-store' });
26	}
27	
28	export async function getAllPosts(): Promise<Post[]> {
29	  return fetchJson<Post[]>('/posts', { next: { revalidate: 60 } });
30	}
31	
32	export async function getStaticBlogParams(): Promise<Array<{ id: string }>> {
33	  const posts = await fetchJson<Post[]>('/posts', { next: { revalidate: 3600 } });
34	
35	  return posts.slice(0, 10).map((post) => ({
36	    id: post.id.toString(),
37	  }));
38	}
39	
40	export async function getPostById(id: string): Promise<Post | null> {
41	  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}/posts/${id}`, {
42	    next: { revalidate: 300 },
43	  });
44	
45	  if (response.status === 404) {
46	    return null;
47	  }
48	
49	  if (!response.ok) {
50	    throw new Error(`Request failed with status ${response.status}`);
51	  }
52	
53	  const post = (await response.json()) as Post;
54	
55	  if (!post?.id) {
56	    return null;
57	  }
58	
59	  return post;
60	}
61	
62	export async function getCommentsByPostId(id: string): Promise<Comment[]> {
63	  return fetchJson<Comment[]>(`/posts/${id}/comments`, {
64	    next: { revalidate: 300 },
65	  });
66	}

